def ref_int(x, y):
    if x > y:
        return -1
    best = -1
    for n in range(x, y + 1):
        if n % 2 == 0:
            if n > best:
                best = n
    return best

def ref_general(x, y):
    if x > y:
        return -1
    hi = math.floor(y)
    if hi % 2 != 0:
        hi -= 1
    if hi >= x:
        return hi
    return -1

